// ===========================================================
// Hermes Agent — Router & Prompt Builder
// Input (dari admin dashboard):
//   { action, payload, source, agent, requested_at }
// Output: { action, system, user, payload }
// ===========================================================
const body = $input.first().json.body || {};
const action = String(body.action || 'chat');
const payload = body.payload || {};

const BLOCK_SCHEMA = payload.block_schema || {};
const BASE = 'Kamu adalah Hermes Agent milik Xinde Labs. Kamu membantu admin sebuah course online yang menjual produk "Build Your Own Personalized Agent". Bahasa Indonesia, santai tapi presisi, tanpa basa-basi. Jangan mengarang angka/statistik.';

const SYSTEM = {
  chat: BASE + ' Jawab pertanyaan admin secara ringkas dan konkret (maks 250 kata).',
  ping: 'Jawab hanya dengan JSON: {"ok":true,"message":"Hermes aktif"}',
  generate_seo_article: BASE + ' Tulis artikel SEO yang jujur dan berguna. Format output: JSON {"title","slug","excerpt","tags":[],"content"}. content = Markdown (## heading, list, bold).',
  generate_blog_article: BASE + ' Tulis artikel blog dari brief admin. Format output: JSON {"title","slug","excerpt","tags":[],"content"}. content = Markdown. Jangan pakai kode fences di luar JSON.',
  analyze_leads_daily: BASE + ' Analisa data lead funnel. Kembalikan ringkasan singkat + 3 rekomendasi aksi konkret. Format output: Markdown teks biasa.',
  analyze_funnel_bottleneck: BASE + ' Analisa bottleneck funnel (stage mana yang paling bocor). Sertakan angka stage, drop-off rate, dan 3 perbaikan spesifik. Format output: Markdown teks biasa.',
  draft_landing_copy: BASE + ' Susun draft copy landing page. Format output: JSON {"blocks":[{type,data}]} dengan type hanya dari: ' + Object.keys(BLOCK_SCHEMA).join(', '),
  generate_funnel_blocks: BASE + ' Susun susunan blok modular untuk satu step funnel. Format output PENTING: JSON array (tanpa teks lain) berisi objek {type, data}. type hanya dari: ' + Object.keys(BLOCK_SCHEMA).join(', ') + '. Ikuti schema di payload.block_schema. Jangan keluarkan teks lain selain JSON.'
};

let user = '';
if (action === 'generate_funnel_blocks') {
  user = [
    'Buat blok untuk step funnel berikut.',
    'Funnel: ' + JSON.stringify(payload.funnel || {}),
    'Step: ' + JSON.stringify(payload.step || {}),
    'Instruksi admin: ' + (payload.brief || '(tidak ada)'),
    'Target CTA: ' + (payload.cta || '(tidak ada)'),
    'Tipe yang diizinkan: ' + JSON.stringify(payload.allowed_block_types || Object.keys(BLOCK_SCHEMA)),
    'Schema tiap tipe: ' + JSON.stringify(BLOCK_SCHEMA),
    'Blok existing: ' + JSON.stringify(payload.existing_blocks || [])
  ].join('\n');
} else if (action === 'generate_blog_article' || action === 'generate_seo_article') {
  user = [
    'Topik: ' + (payload.topic || payload.subject || ''),
    'Keyword: ' + (payload.keyword || ''),
    'Tone: ' + (payload.tone || 'santai, Bahasa Indonesia'),
    'Panjang: ' + (payload.length || '800-1200 kata'),
    'Instruksi tambahan: ' + (payload.extra || payload.instruction || '(tidak ada)'),
    payload.publish ? 'Langsung simpan artikel ke blog_posts lalu kembalikan JSON artikelnya.' : ''
  ].filter(Boolean).join('\n');
} else if (action === 'draft_landing_copy') {
  user = [
    'Tujuan landing: ' + (payload.goal || ''),
    'Tone: ' + (payload.tone || 'santai'),
    'Buat 3-5 blok: hero, benefit, pricing, faq, cta.',
    'Schema: ' + JSON.stringify(BLOCK_SCHEMA)
  ].join('\n');
} else if (action === 'chat') {
  user = 'Instruksi admin: ' + (payload.message || '') + '\n\nRiwayat:\n' + JSON.stringify(payload.history || []);
} else if (action === 'analyze_leads_daily') {
  user = 'Rentang hari: ' + (payload.range_days || 1) + '. Analisa lead funnel hari ini.';
} else if (action === 'analyze_funnel_bottleneck') {
  user = 'Rentang hari: ' + (payload.range_days || 7) + '. Cari bottleneck funnel & rekomendasi perbaikan.';
} else {
  user = JSON.stringify(payload);
}

return { json: { action, system: SYSTEM[action] || SYSTEM.chat, user, payload } };

// Normalisasi output LLM sesuai action.
const req = $('Code: Route & Build Prompt').first().json;
const resp = $input.first().json;
let content = '';
try {
  content = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || resp.output || resp.text || '';
} catch (e) { content = ''; }
content = String(content || '').trim();

// Buang kode fences markdown yang sering dipakai LLM
const fence = content.match(/^```(?:json)?\s*([\s\S]*?)```$/i);
if (fence) content = fence[1].trim();

let output = content;
if (req.action === 'generate_funnel_blocks' || req.action === 'draft_landing_copy') {
  try {
    const parsed = JSON.parse(content);
    output = Array.isArray(parsed) ? parsed : (parsed.blocks || parsed);
  } catch (e) {
    output = content;
  }
} else if (req.action === 'generate_blog_article' || req.action === 'generate_seo_article') {
  try {
    const parsed = JSON.parse(content);
    output = parsed;
  } catch (e) {
    output = { content };
  }
}

return { json: { action: req.action, output, duration_hint: 'llm' } };

// ===========================================================
// Hermes — Siapkan data publikasi artikel
// ===========================================================
const norm = $('Code: Normalize Output').first().json;
const req = $('Code: Route & Build Prompt').first().json;
const payload = req.payload || {};
const isArticle = norm.action === 'generate_seo_article' || norm.action === 'generate_blog_article';
const wantPublish = isArticle && !!payload.publish;
const a = (norm.output && typeof norm.output === 'object' && !Array.isArray(norm.output)) ? norm.output : {};
const slugify = (s) => String(s || '').toLowerCase().trim().replace(/[^a-z0-9\s-]/g, '').replace(/[\s_]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').slice(0, 90);
const title = String(a.title || payload.title || 'Artikel Hermes').trim();
const slug = slugify(a.slug || title);
const article = {
  title: title,
  slug: slug,
  excerpt: a.excerpt ? String(a.excerpt) : (payload.excerpt ? String(payload.excerpt) : null),
  content: String(a.content || ''),
  tags: Array.isArray(a.tags) ? a.tags.map((t) => String(t)).slice(0, 10) : [],
  status: wantPublish ? 'published' : 'draft',
  published_at: wantPublish ? new Date().toISOString() : null,
  author: 'Xinde Labs'
};

return { json: { action: norm.action, output: norm.output, publish: wantPublish, article } };

// ===========================================================
// Hermes — Susun respons final ke admin dashboard
// ===========================================================
const prep = $('Code: Siapkan Publish').first().json;
let published = null;
let publishError = null;
if (prep.publish) {
  try {
    const r = $('HTTP: Publish blog_posts').first().json || {};
    const sc = r.statusCode || (r.headers && (r.headers['status-code'] || r.headers['Status-Code'])) || 0;
    published = sc >= 200 && sc < 300;
    if (!published) publishError = r.error || r.message || ('HTTP ' + sc);
  } catch (e) {
    published = false;
    publishError = String((e && e.message) || e);
  }
}

return { json: { response: {
  ok: true,
  action: prep.action,
  output: prep.output,
  publish_requested: !!prep.publish,
  published: published,
  publish_error: publishError,
  article: prep.publish ? prep.article : undefined
} } };
